		if err != nil {
			return fmt.Errorf("failed to create transcript chunk blob: %w", err)
		}
		entries[entryPath] = object.TreeEntry{
			Name: entryPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

