		attr.HumanAdded == 0 &&
		attr.HumanModified == 0 &&
		attr.HumanRemoved == 0 &&
		attr.TotalCommitted == 0 &&
		attr.TotalLinesChanged == 0 &&
		attr.AgentPercentage == 0 &&
